({
  /**
   * Initializes the object's model state.
   */
  init(msg) {
    this.data = {
      extractedCount: 0,
      validatedCount: 0
    };
    this._checkInvariants();
    return { initialized: true };
  },

  /**
   * Invariant verification for object state.
   */
  _checkInvariants() {
    if (this.data) {
      this.invariant(
        typeof this.data === 'object' && this.data !== null,
        "Model data must be an object"
      );
      this.invariant(
        typeof this.data.extractedCount === 'number' && this.data.extractedCount >= 0,
        "extractedCount must be a non-negative number"
      );
      this.invariant(
        typeof this.data.validatedCount === 'number' && this.data.validatedCount >= 0,
        "validatedCount must be a non-negative number"
      );
    }
  },

  /**
   * Extracts links from a markdown string.
   * @param {Object} msg - Message envelope
   * @param {Object} msg.payload - Payload containing { markdown: string }
   * @returns {Array<{ text: string, url: string, isAnchor: boolean }>}
   */
  extractLinks(msg) {
    this.ensure(typeof msg === 'object' && msg !== null, "Message must be an object");
    this.ensure(typeof msg.payload === 'object' && msg.payload !== null, "Payload must be an object");
    this.ensure(typeof msg.payload.markdown === 'string', "markdown property must be a string");

    const markdown = msg.payload.markdown;
    const links = this._extractLinks(markdown);

    if (!this.data) {
      this.data = { extractedCount: 0, validatedCount: 0 };
    }
    this.data.extractedCount += links.length;
    this._checkInvariants();

    this.ensure(Array.isArray(links), "Result must be an array");
    for (const item of links) {
      this.ensure(
        typeof item.text === 'string' &&
        typeof item.url === 'string' &&
        typeof item.isAnchor === 'boolean',
        "Each extracted link must contain text (string), url (string), and isAnchor (boolean)"
      );
    }

    return links;
  },

  /**
   * Validates an array of URLs or link objects.
   * @param {Object} msg - Message envelope
   * @param {Object} msg.payload - Payload containing { urls: Array<string | { url: string }> }
   * @returns {Array<{ url: string, valid: boolean, isAnchor: boolean, protocol?: string, reason?: string }>}
   */
  validateUrls(msg) {
    this.ensure(typeof msg === 'object' && msg !== null, "Message must be an object");
    this.ensure(typeof msg.payload === 'object' && msg.payload !== null, "Payload must be an object");
    this.ensure(Array.isArray(msg.payload.urls), "urls property must be an array");

    const rawList = msg.payload.urls;
    const results = rawList.map(item => this._validateSingleUrl(item));

    if (!this.data) {
      this.data = { extractedCount: 0, validatedCount: 0 };
    }
    this.data.validatedCount += rawList.length;
    this._checkInvariants();

    this.ensure(Array.isArray(results), "Result must be an array of validation records");
    return results;
  },

  /**
   * Pure model helper: extracts standard markdown inline links, excluding images.
   */
  _extractLinks(markdown) {
    const links = [];
    // Matches [text](url "title"), capturing optional leading ! to exclude image tags
    const pattern = /(!)?\[([^\]]*)\]\(([^)\s]+)(?:\s+(?:"[^"]*"|'[^']*'))?\)/g;
    let match;

    while ((match = pattern.exec(markdown)) !== null) {
      const isImage = Boolean(match[1]);
      if (!isImage) {
        const text = match[2];
        const rawUrl = match[3];
        const isAnchor = rawUrl.startsWith('#');
        links.push({
          text,
          url: rawUrl,
          isAnchor
        });
      }
    }

    return links;
  },

  /**
   * Pure model helper: validates a single URL or URL descriptor.
   */
  _validateSingleUrl(entry) {
    const rawUrl = typeof entry === 'string'
      ? entry
      : (entry && typeof entry.url === 'string' ? entry.url : '');
    const trimmed = rawUrl.trim();

    if (!trimmed) {
      return {
        url: rawUrl,
        valid: false,
        isAnchor: false,
        reason: 'Empty or invalid URL string'
      };
    }

    // Anchor links (#section)
    if (trimmed.startsWith('#')) {
      return {
        url: rawUrl,
        valid: true,
        isAnchor: true,
        protocol: 'anchor'
      };
    }

    // Relative links (/path, ./path, ../path)
    if (trimmed.startsWith('/') || trimmed.startsWith('./') || trimmed.startsWith('../')) {
      return {
        url: rawUrl,
        valid: true,
        isAnchor: false,
        protocol: 'relative'
      };
    }

    // Protocol / absolute links
    const schemeMatch = trimmed.match(/^([a-zA-Z][a-zA-Z0-9+.-]*):/);
    if (schemeMatch) {
      const scheme = schemeMatch[1].toLowerCase();

      if (scheme === 'http' || scheme === 'https' || scheme === 'ftp' || scheme === 'ftps') {
        const isValid = /^(https?|ftps?):\/\/[^\s/$.?#].[^\s]*$/i.test(trimmed);
        return {
          url: rawUrl,
          valid: isValid,
          isAnchor: false,
          protocol: scheme,
          ...(isValid ? {} : { reason: 'Malformed network URL structure' })
        };
      }

      if (scheme === 'mailto' || scheme === 'tel') {
        return {
          url: rawUrl,
          valid: true,
          isAnchor: false,
          protocol: scheme
        };
      }

      return {
        url: rawUrl,
        valid: true,
        isAnchor: false,
        protocol: scheme
      };
    }

    return {
      url: rawUrl,
      valid: false,
      isAnchor: false,
      reason: 'Unrecognized URL scheme or relative path'
    };
  }
})
